    out=[row[:] for row in g]
    for i in range(h):
        for j in range(w):
            if out[i][j]==marker:
                out[i][j]=4
                # fill between marker and bottom bar's column
                lo,hi=(j+1,cB-1) if cB>j else (cB+1,j-1)
                for jj in range(lo,hi+1):
                    if out[i][jj]==bg: out[i][jj]=marker
                # top block corresponding row
                rel=i-bottom[0]
                tr=top[0]+rel
                if 0<=tr<h:
                    for jj in range(w):
                        if out[tr][jj]==bg: out[tr][jj]=marker
