def segments(cells):
    # group straight contiguous segments: vertical segs (same col) and horizontal (same row)
    from collections import defaultdict
    byc=defaultdict(list); byr=defaultdict(list)
    for i,j in cells: byc[j].append(i); byr[i].append(j)
    segs=[]
    for c,rows in byc.items():
        rows=sorted(rows); cur=[rows[0]]
        for r in rows[1:]:
            if r==cur[-1]+1: cur.append(r)
            else: segs.append(('V',c,cur)); cur=[r]
        segs.append(('V',c,cur))
    for r,cols in byr.items():
        cols=sorted(cols); cur=[cols[0]]
        for c in cols[1:]:
            if c==cur[-1]+1: cur.append(c)
            else: segs.append(('H',r,cur)); cur=[c]
        segs.append(('H',r,cur))
    return segs
